int main(){try{auto root=std::filesystem::temp_directory_path()/"AudioNLE-source-runtime";std::filesystem::create_directories(root);auto file=root/"prepared.anleprp";PreparedArtifactKey key{3,1,77,1,48000};writePreparedFixtureArtifact(file,key,20);auto ni=makeRuntimeIdentity(1,48000,Admission::NativeRate),ri=makeRuntimeIdentity(2,44100,Admission::GuaranteedRealtime),pi=makeRuntimeIdentity(3,48000,Admission::PreparedRequired);SourceRuntime native(ni),realtime(ri),prepared(pi,file);SharedSourceWorker worker;worker.add(native);worker.add(realtime);worker.add(prepared);ClipRuntimeView nv{0,0,512,ni},rv{0,0,512,ri},pv{0,0,512,pi};SourceNode n(native),r(realtime),p(prepared);std::array<float,256>a{},b{},c{};if(n.process(nv,0,256,a.data())!=SourceRenderResult::Ready||r.process(rv,0,256,b.data())!=SourceRenderResult::Ready||p.process(pv,0,256,c.data())!=SourceRenderResult::Unavailable)throw std::runtime_error("route");worker.drain();if(p.process(pv,0,256,c.data())!=SourceRenderResult::Ready||native.realtimeCalls()||prepared.realtimeCalls()||!realtime.realtimeCalls())throw std::runtime_error("reload");std::error_code e;std::filesystem::remove_all(root,e);std::cout<<"source runtime routes PASS\n";return 0;}catch(std::exception const&e){std::cerr<<e.what()<<'\n';return 1;}}
